    //
    aIngress = 0xEA1CEFEA3416FF58ULL;
    aCarry = 0xFC4E003BB48BE917ULL;
    aWandererA = 0xB6E1476DFF0175AAULL;
    aWandererB = 0xDA36FCBE9C59A64AULL;
